arguments.command:
curl -s -X POST https://slack.com/api/users.list -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERROR',d); sys.exit(1)
members=d['members']
for m in members:
    if m.get('is_owner'):
        print('OWNER',m['id'],m['profile']['real_name'])
print('TOTAL',len(members))
"

